const item = $input.first().json;
const attachments = item.attachments || [];
const hasAudio = attachments.some(a => ['audio','voice','audio/ogg','audio/mpeg'].includes(a.type || a.mime_type));
const hasImage = attachments.some(a => ['image','image/jpeg','image/png','image/jpg'].includes(a.type || a.mime_type));
const hasDocument = attachments.some(a => ['document','application/pdf','text/plain','application/msword'].includes(a.type || a.mime_type));
const audioAttachment = hasAudio ? attachments.find(a => ['audio','voice','audio/ogg','audio/mpeg'].includes(a.type || a.mime_type)) : null;
const imageAttachment = hasImage ? attachments.find(a => ['image','image/jpeg','image/png','image/jpg'].includes(a.type || a.mime_type)) : null;
const docAttachment = hasDocument ? attachments.find(a => ['document','application/pdf','text/plain','application/msword'].includes(a.type || a.mime_type)) : null;
return [{
  json: {
    ...item,
    _attachment_type: hasAudio ? 'audio' : (hasImage ? 'image' : (hasDocument ? 'document' : 'none')),
    _audio_url: audioAttachment ? (audioAttachment.url || audioAttachment.link || '') : '',
    _image_url: imageAttachment ? (imageAttachment.url || imageAttachment.link || '') : '',
    _doc_url: docAttachment ? (docAttachment.url || docAttachment.link || '') : '',
    _doc_mime: docAttachment ? (docAttachment.mime_type || docAttachment.type || 'application/octet-stream') : ''
  }
}];

const item = $input.first().json;
const transcribed = item.text || '';
return [{ json: { ...item, transcribed_text: transcribed, message: (item.message || '') + ' [Audio transcrito]: ' + transcribed } }];

const item = $input.first().json;
const binary = $input.first().binary?.data;
let docText = '';
if (binary && binary.data) {
  try {
    docText = Buffer.from(binary.data, 'base64').toString('utf-8').substring(0, 8000);
  } catch (e) {
    docText = '[No se pudo extraer texto del documento]';
  }
} else {
  docText = '[Documento sin contenido accesible]';
}
return [{ json: { ...item, document_text: docText, message: (item.message || '') + ' [Documento]: ' + docText.substring(0, 500) } }];

const item = $input.first().json;
const transcribed = item.transcribed_text || '';
const imgCtx = item.image_context || '';
const docCtx = item.document_text || '';
const baseMsg = item.message || '';
let enrichedMsg = baseMsg;
if (imgCtx) enrichedMsg += '\n' + imgCtx;
if (docCtx && docCtx.length > 10) enrichedMsg += '\n[Documento adjunto]: ' + docCtx.substring(0, 1000);
return [{ json: { ...item, enriched_message: enrichedMsg } }];

const base = $('Build Agent Prompt').item.json;
const payload = $input.first().json || {};
const kb = String(payload.kb_context || '').trim();
const merged = kb ? `${base.enriched_message || base.message || ''}\n\n[Contexto KB PostgreSQL]\n${kb}` : (base.enriched_message || base.message || '');
return [{ json: { ...base, kb_context: kb, enriched_message: merged } }];

const base = $('Apply KB Context').item.json || $('Build Agent Prompt').item.json || {};
const ai = $input.first().json || {};
return [{ json: { ...base, ...ai } }];

